INSERT INTO public.actualites (titre, resume, contenu, categorie, auteur_id, auteur_nom, image_emoji, created_at) VALUES
('Alerte : Grippe Aviaire detectee dans la region de Thies', 'Des cas de grippe aviaire H5N1 ont ete signales dans plusieurs elevages. Les autorites recommandent des mesures preventives immediates.', 'Des cas de grippe aviaire H5N1 ont ete confirmes dans la region de Thies. Mesures immediates : isoler les animaux malades, contacter votre veterinaire, ne pas deplacer les volailles, desinfecter les equipements. Numero urgence Ministere Elevage : 33 889 10 10.', 'virus', 'admin', 'AviConnect Admin', '🦠', '2026-07-05'),
('Calendrier de vaccination 2026 pour les poulets de chair', 'Le nouveau calendrier vaccinal recommande par le DIREL est disponible. Retrouvez les dates et vaccins essentiels pour proteger votre elevage.', 'Calendrier DIREL 2026 : Jour 1 - Marek + Newcastle HB1. Jour 7-10 - Gumboro + Bronchite Infectieuse. Jour 18-21 - Rappel Newcastle La Sota + Rappel Gumboro. Jour 35 - Newcastle vaccin huileux injection. Contactez votre veterinaire pour adapter ce protocole.', 'vaccin', 'admin', 'AviConnect Admin', '💉', '2026-07-01'),
('Prix du mais : hausse de 15% attendue ce trimestre', 'Les cours du mais sur les marches internationaux impactent les prix locaux de l aliment. Comment anticiper la hausse des couts d elevage.', 'Les prix du mais ont augmente de 15%. Impact prevu sur le cout de l aliment : +8 a 12%. Conseils : acheter et stocker avant la hausse, negocier des contrats a prix fixe, reduire les gaspillages, considerer le sorgho local. Contacter la FAFA-SN pour des achats groupes.', 'marche', 'admin', 'AviConnect Admin', '📈', '2026-06-28'),
('Bonnes pratiques de biosecurite en elevage avicole', 'Adoptez ces 10 regles d or pour proteger votre elevage contre les maladies et ameliorer vos performances.', '10 regles de biosecurite : 1. Vetements propres obligatoires. 2. Pediluves a chaque entree. 3. Quarantaine 2-3 semaines pour tout nouvel animal. 4. Eau traitee a la javel. 5. Nettoyage quotidien des fientes. 6. Vide sanitaire 3 semaines minimum. 7. Grillages contre oiseaux sauvages. 8. Deratisation reguliere. 9. Limiter les visites. 10. Incinerer les carcasses.', 'conseil', 'admin', 'AviConnect Admin', '💡', '2026-06-20');
